// --------------------------------------------------------------------------
// 调研页左侧菜单结构：与需求演示侧边栏 LeftTreeSidebar 的分组层级保持一致。
// 大组标题沿用 GROUP_TITLES；子分组按演示侧边栏顺序登记表单编码：
// - 注册表中不存在的编码自动跳过；
// - 子分组未覆盖到的注册表编码追加在本组末尾（不丢条目）；
// - BA / BF 无子分组（subGroups 为 null）。
// --------------------------------------------------------------------------
interface MenuSubGroupDef {
  title: string | null;
  codes: string[] | null;
  /**
   * 嵌套子分组（可选）：在父级子目录内部再分一层「带标题的分组」。
   * 仅登记标题与编码，不改变父级 codes 的来源与顺序：
   * 渲染位置由子分组 codes 在父级 codes 中的出现顺序决定（首个命中编码处成组展开），
   * 组内行序 = 子分组 codes 顺序。未登记 children 的子目录渲染与既有行为完全一致。
   */
  children?: MenuSubGroupDef[] | null;
}

interface MenuGroupDef {
  group: BudgetFormDef['group'];
  menuGroup: string;
  title: string;
  subGroups: MenuSubGroupDef[] | null;
}

