const BUDGET_PROCESS_EDGES: BudgetProcessEdge[] = [
  { from: 'base', to: 'assume', label: '基础字典' },
  { from: 'assume', to: 'collect', label: '参数就绪' },
  { from: 'collect', to: 'bb1' },
  { from: 'collect', to: 'bb2' },
  { from: 'collect', to: 'bb3', label: '物料需求' },
  { from: 'collect', to: 'bb5', label: '费用需求' },
  { from: 'collect', to: 'bb4' },
  { from: 'bb1', to: 'bb2', label: '排产' },
  { from: 'bb2', to: 'bb3', label: '采购量' },
  { from: 'bb1', to: 'bf' }, { from: 'bb2', to: 'bf' }, { from: 'bb3', to: 'bf' }, { from: 'bb5', to: 'bf' }, { from: 'bb4', to: 'bf' },
  { from: 'bf', to: 'bo', label: '三表汇总' },
];

function processEdgePath(nodeById: Map<string, BudgetProcessNode>, edge: BudgetProcessEdge): string | null {
  const from = nodeById.get(edge.from);
  const to = nodeById.get(edge.to);
  if (!from || !to) return null;
  const x0 = from.x + from.w;
  const y0 = from.y + from.h / 2;
  const x1 = to.x;
  const y1 = to.y + to.h / 2;
  const midX = (x0 + x1) / 2;
  return `M${x0},${y0} C${midX},${y0} ${midX},${y1} ${x1},${y1}`;
}

const BudgetProcessFlowDiagram: React.FC = () => {
  const nodeById = useMemo(() => new Map(BUDGET_PROCESS_NODES.map((n) => [n.id, n])), []);
  const width = 1160;
  const height = 360;
  return (
    <div className="overflow-x-auto border border-slate-200 dark:border-slate-700 rounded-md bg-white dark:bg-slate-900 p-2">
      <svg width={width} height={height} viewBox={`0 0 ${width} ${height}`} className="block">
        <defs>
          <marker id="procArrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse">
            <path d="M0,0 L10,5 L0,10 z" fill="#94a3b8" />
          </marker>
        </defs>
        {BUDGET_PROCESS_EDGES.map((e, i) => {
          const path = processEdgePath(nodeById, e);
          if (!path) return null;
          const from = nodeById.get(e.from)!;
          const to = nodeById.get(e.to)!;
          const midX = (from.x + from.w + to.x) / 2;
          const midY = (from.y + from.h / 2 + to.y + to.h / 2) / 2;
          return (
            <g key={i}>
              <path d={path} fill="none" stroke="#94a3b8" strokeWidth={1.4} strokeOpacity={0.55} markerEnd="url(#procArrow)" />
              {e.label && (
                <text x={midX} y={midY - 5} fontSize={9} fill="#64748b" textAnchor="middle" style={{ paintOrder: 'stroke', stroke: '#ffffff', strokeWidth: 3 }}>{e.label}</text>
              )}
            </g>
          );
        })}
        {BUDGET_PROCESS_NODES.map((n) => (
          <g key={n.id}>
            <rect x={n.x} y={n.y} width={n.w} height={n.h} rx={6} fill={n.color} fillOpacity={0.12} stroke={n.color} strokeWidth={1.4} />
            <text x={n.x + 8} y={n.y + 16} fontSize={11} fontWeight={700} fill={n.color}>{n.title}</text>
            <text x={n.x + n.w - 8} y={n.y + 16} fontSize={10} fontWeight={700} fill={n.color} textAnchor="end">{n.step}</text>
            <foreignObject x={n.x + 6} y={n.y + 24} width={n.w - 12} height={n.h - 30}>
              <div style={{ fontSize: 8.5, lineHeight: 1.35, color: '#334155', overflow: 'hidden' }}>{n.desc}</div>
            </foreignObject>
          </g>
        ))}
      </svg>
    </div>
  );
};

