  'BAA.7': '采购付款额测算比例表的长期规划登记：按「预算项目×预算部门」维护预付款与验收付款的分月比例，含设备类/物料类采购付款比例表两个子Tab，是后续年度采购付款节奏比例的统一登记入口。本预算年度不需要实现和使用——BB.3.1设备及无形资产采购预算、BB.3.3物料类采购预算的预付款比例与验收付款金额由各表按月自行填报，不强制从本表取数、不做公式联动。仅参数、不生成分录，不区分法人。',
